module MaximumSubarraySum(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input signed [31:0] a [0:15],\n    output reg signed [31:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COMPUTE_DIFF = 3'd1;\n    localparam [2:0] KADANE_EV = 3'd2;\n    localparam [2:0] KADANE_OD = 3'd3;\n    localparam [2:0] FINISH = 3'd4;\n\n    // Internal registers\n    reg [2:0] state;\n    reg [3:0] idx;\n    reg signed [31:0] max_ev, max_od;\n    reg signed [31:0] curr_ev, curr_od;\n    reg signed [31:0] diff_val;\n    reg signed [31:0] term_ev, term_od;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 32'sd0;\n            done <= 1'b0;\n            cycle_count <= 8'd0;\n            idx <= 4'd0;\n            max_ev <= 32'sd0;\n            max_od <= 32'sd0;\n            curr_ev <= 32'sd0;\n            curr_od <= 32'sd0;\n            diff_val <= 32'sd0;\n            term_ev <= 32'sd0;\n            term_od <= 32'sd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        state <= COMPUTE_DIFF;\n                        idx <= 4'd0;\n                        max_ev <= 32'sd0;\n                        max_od <= 32'sd0;\n                        curr_ev <= 32'sd0;\n                        curr_od <= 32'sd0;\n                    end\n                end\n\n                COMPUTE_DIFF: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (idx < (n - 4'd1)) begin\n                        // Compute |a[i] - a[i+1]|\n                        diff_val <= (a[idx] > a[idx + 4'd1]) ? (a[idx] - a[idx + 4'd1]) : (a[idx + 4'd1] - a[idx]);\n                        // Compute ev = diff * (-1)^i\n                        if (idx[0] == 1'b0) begin\n                            term_ev <= (a[idx] > a[idx + 4'd1]) ? (a[idx] - a[idx + 4'd1]) : (a[idx + 4'd1] - a[idx]);\n                            term_od <= -((a[idx] > a[idx + 4'd1]) ? (a[idx] - a[idx + 4'd1]) : (a[idx + 4'd1] - a[idx]));\n                        end else begin\n                            term_ev <= -((a[idx] > a[idx + 4'd1]) ? (a[idx] - a[idx + 4'd1]) : (a[idx + 4'd1] - a[idx]));\n                            term_od <= (a[idx] > a[idx + 4'd1]) ? (a[idx] - a[idx + 4'd1]) : (a[idx + 4'd1] - a[idx]);\n                        end\n                        state <= KADANE_EV;\n                    end else begin\n                        state <= FINISH;\n                    end\n                    idx <= idx + 4'd1;\n                end\n\n                KADANE_EV: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    // Kadane for ev: curr_ev = max(term_ev, curr_ev + term_ev)\n                    if (curr_ev + term_ev > term_ev) begin\n                        curr_ev <= curr_ev + term_ev;\n                    end else begin\n                        curr_ev <= term_ev;\n                    end\n                    // Update max_ev\n                    if (curr_ev + term_ev > max_ev) begin\n                        max_ev <= curr_ev + term_ev;\n                    end else if (term_ev > max_ev) begin\n                        max_ev <= term_ev;\n                    end else begin\n                        max_ev <= max_ev;\n                    end\n                    state <= KADANE_OD;\n                end\n\n                KADANE_OD: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    // Kadane for od: curr_od = max(term_od, curr_od + term_od)\n                    if (curr_od + term_od > term_od) begin\n                        curr_od <= curr_od + term_od;\n                    end else begin\n                        curr_od <= term_od;\n                    end\n                    // Update max_od\n                    if (curr_od + term_od > max_od) begin\n                        max_od <= curr_od + term_od;\n                    end else if (term_od > max_od) begin\n                        max_od <= term_od;\n                    end else begin\n                        max_od <= max_od;\n                    end\n                    // Check if more elements to process\n                    if (idx < (n - 4'd1)) begin\n                        state <= COMPUTE_DIFF;\n                    end else begin\n                        state <= FINISH;\n                    end\n                end\n\n                FINISH: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    // Return max of max_ev and max_od\n                    if (max_ev > max_od) begin\n                        result <= max_ev;\n                    end else begin\n                        result <= max_od;\n                    end\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule}